 out.push({json:{row:row,id:g(0),firm:firm,startup:startup,owner:owner,mb:mb,url:'https://sidanaventures.app.n8n.cloud/webhook/'+path,payload:{secret:'sv-mail-2026-09-17-Kq7',thread_id:thread,expect_last_from:iv.email,allow_external_start:true,to_only:[iv.email],html:html,dry:false},evidence:evidence}});});
